import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    book = {}  # id -> {'side','price','qty','time','active'}

    def clean_buy():
        while buy_heap:
            negprice, t, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            break

    def clean_sell():
        while sell_heap:
            price, t, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            break

    for idx, order in enumerate(orders):
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        time = idx

        if side == 'buy':
            # match against sell_heap
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sprice, stime, sid = sell_heap[0]
                if typ != 'market' and sprice > price:
                    break
                sinfo = book[sid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, sid, sprice, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                if sinfo['qty'] <= 0:
                    sinfo['active'] = False
                    heapq.heappop(sell_heap)
                # if partially filled, keep at top for next check but remaining may be 0
                if remaining == 0:
                    break
                clean_sell()
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': time, 'active': True}
                heapq.heappush(buy_heap, (-price, time, oid))
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negprice, btime, bid = buy_heap[0]
                bprice = -negprice
                if typ != 'market' and bprice < price:
                    break
                binfo = book[bid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([bid, oid, bprice, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                if binfo['qty'] <= 0:
                    binfo['active'] = False
                    heapq.heappop(buy_heap)
                if remaining == 0:
                    break
                clean_buy()
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': time, 'active': True}
                heapq.heappush(sell_heap, (price, time, oid))

    return trades

